import{u as a}from"./useCanonical-D15JrJam.mjs";import{c as e,Y as t,V as i}from"./server.mjs";import{d as s}from"../routes/renderer.mjs";import"../_/nitro.mjs";import"node:buffer";import"node:timers";import"node:events";import"node:process";import"cloudflare:workers";const o=t.defineComponent({__name:"ai",__ssrInlineRender:!0,setup:e=>(a("/ai"),i({title:"AI Usage Policy – Yannosay Productions",meta:[{name:"description",content:"Yannosay Productions' public declaration on generative AI: a strict human-first policy covering creative work, technical assistance, and data security."},{property:"og:title",content:"AI Usage Restrictions Policy"},{property:"og:description",content:"A strict human-first policy governing the use of generative AI across all Yannosay Productions operations."}]}),(a,e,i,o)=>{e(`<section${s(t.mergeProps({class:"ai-page"},o))} data-v-21ae3380><div class="ai-page__container" data-v-21ae3380><header class="doc-header" data-v-21ae3380><p class="doc-header__eyebrow" data-v-21ae3380>Public Declaration</p><h1 class="doc-header__title" data-v-21ae3380>AI Usage Restrictions Policy</h1><p class="doc-header__lede" data-v-21ae3380> Safeguarding human expression, legal compliance, and quality control in an era of automated content saturation. </p></header><dl class="doc-meta" data-v-21ae3380><div class="doc-meta__row" data-v-21ae3380><dt class="doc-meta__label" data-v-21ae3380>Document ID</dt><dd class="doc-meta__value" data-v-21ae3380>AIP-2024-001</dd></div><div class="doc-meta__row" data-v-21ae3380><dt class="doc-meta__label" data-v-21ae3380>Effective</dt><dd class="doc-meta__value" data-v-21ae3380>27 September 2026</dd></div><div class="doc-meta__row" data-v-21ae3380><dt class="doc-meta__label" data-v-21ae3380>Revision</dt><dd class="doc-meta__value" data-v-21ae3380>1.0</dd></div><div class="doc-meta__row" data-v-21ae3380><dt class="doc-meta__label" data-v-21ae3380>Status</dt><dd class="doc-meta__value" data-v-21ae3380><span class="doc-meta__status" data-v-21ae3380>Enforced</span></dd></div></dl><nav class="doc-toc" aria-label="Contents" data-v-21ae3380><p class="doc-toc__label" data-v-21ae3380>Contents</p><ol class="doc-toc__list" data-v-21ae3380><li data-v-21ae3380><a href="#preamble" data-v-21ae3380>Preamble</a></li><li data-v-21ae3380><a href="#section-1" data-v-21ae3380>Executive Summary &amp; Core Stance</a></li><li data-v-21ae3380><a href="#section-2" data-v-21ae3380>Strict Creative Restrictions</a></li><li data-v-21ae3380><a href="#section-3" data-v-21ae3380>Approved Technical AI Uses</a></li><li data-v-21ae3380><a href="#section-4" data-v-21ae3380>Transparency, Accountability &amp; Safeguards</a></li><li data-v-21ae3380><a href="#section-5" data-v-21ae3380>Conclusion</a></li></ol></nav><article class="doc-body" data-v-21ae3380><section id="preamble" class="doc-section" data-v-21ae3380><h2 class="doc-section__title" data-v-21ae3380><span class="doc-section__num" data-v-21ae3380>§0</span> Preamble </h2><p data-v-21ae3380> This document establishes the definitive policy regarding the use of Generative Artificial Intelligence (AI) within all creative and technical operations. It is designed to safeguard the integrity of human expression, ensure legal compliance, and maintain the highest standards of quality control in an era of automated content saturation. </p><p data-v-21ae3380> This policy is binding upon all personnel, including full-time employees, part-time staff, freelance contractors, external vendors, and any third parties engaged in production workflows. By participating in any capacity within our operational ecosystem, all parties implicitly agree to adhere to the restrictions and mandates set forth herein. </p></section><section id="section-1" class="doc-section" data-v-21ae3380><h2 class="doc-section__title" data-v-21ae3380><span class="doc-section__num" data-v-21ae3380>§1</span> Executive Summary &amp; Core Stance </h2><div class="doc-subsection" data-v-21ae3380><h3 class="doc-subsection__title" data-v-21ae3380><span class="doc-subsection__num" data-v-21ae3380>1.1</span> The “Human-First” Philosophy </h3><p data-v-21ae3380> The core operational philosophy is defined as “Human-First.” This stance is not merely a preference but a fundamental requirement for the authenticity and quality of our output. </p><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>A</span> Original Creative Vision </h4><p data-v-21ae3380> Generative AI models function by synthesizing existing data, inherently lacking the capacity for genuine intentionality, lived experience, or original thought. True artistry requires a human perspective that cannot be algorithmically generated. We strictly prioritize the unique nuance, emotional resonance, and intentionality that only a human creator can provide. </p></div><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>B</span> Higher Quality Control </h4><p data-v-21ae3380> While generative tools can produce rapid output, they frequently suffer from structural inconsistencies, “hallucinations,” and a lack of cohesive narrative logic. The pursuit of excellence demands deliberate craftsmanship over automated convenience. Human oversight ensures that every element serves a purpose and meets rigorous standards of technical and artistic integrity. </p></div><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>C</span> Resistance to Industry Saturation </h4><p data-v-21ae3380> The market is currently flooded with synthetic media. To distinguish authentic work from automated content, we maintain a strict zero-tolerance policy regarding generative assets. This ensures that our output remains distinct, ethically sourced, and legally defensible. </p></div></div><div class="doc-subsection" data-v-21ae3380><h3 class="doc-subsection__title" data-v-21ae3380><span class="doc-subsection__num" data-v-21ae3380>1.2</span> Scope &amp; Applicability </h3><p data-v-21ae3380> This policy applies universally across all operations and media formats, including but not limited to: </p><ul class="doc-list" data-v-21ae3380><li data-v-21ae3380>Visual Arts (Illustration, Graphic Design, Concept Art)</li><li data-v-21ae3380>Motion Media (Video Production, Animation, VFX)</li><li data-v-21ae3380>Audio Media (Music Composition, Sound Design, Voiceover)</li><li data-v-21ae3380>Written Content (Scripts, Narrative Design, Documentation)</li><li data-v-21ae3380>Technical Development (Codebases, Web Architecture)</li></ul><p data-v-21ae3380> The restrictions herein apply to all stages of production: conceptualization, drafting, final asset creation, and post-production. </p></div></section><section id="section-2" class="doc-section" data-v-21ae3380><h2 class="doc-section__title" data-v-21ae3380><span class="doc-section__num" data-v-21ae3380>§2</span> Strict Creative Restrictions </h2><div class="doc-subsection" data-v-21ae3380><h3 class="doc-subsection__title" data-v-21ae3380><span class="doc-subsection__num" data-v-21ae3380>2.1</span> Zero-Tolerance Media Policy </h3><p data-v-21ae3380> The use of Generative AI to create, assist in creating, or refine any creative asset is strictly prohibited. This prohibition applies to final assets as well as “draft,” “concept,” or “placeholder” materials. </p><p data-v-21ae3380>Specifically, the following applications are forbidden:</p><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>A</span> Illustrations, Artwork, and Graphic Design </h4><p data-v-21ae3380> The use of AI image generators (e.g., diffusion models, GANs, or similar image synthesis tools) is banned. All visual assets must be created through manual digital painting, vector illustration, photography, or traditional mediums. Sketching, line art, coloring, and texturing must be performed by human hands. </p></div><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>B</span> Video Production, Visual Effects, and Animation </h4><p data-v-21ae3380> The use of AI video generators, frame interpolation tools for the creation of new frames, or AI-driven rotoscoping that synthesizes content is prohibited. All motion graphics, 3D modeling, rigging, animation, and compositing must be executed by human artists. Visual effects must be based on real footage or manually created digital assets. </p></div><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>C</span> Music Composition, Audio Tracks, and Voiceovers </h4><p data-v-21ae3380> The use of AI music generators, AI voice cloning, or synthetic audio production is banned. All music must be composed and performed by human musicians. All voiceovers must be recorded by human talent. Synthesized vocals or algorithmic soundscapes are not permitted in any deliverable. </p></div></div><div class="doc-subsection" data-v-21ae3380><h3 class="doc-subsection__title" data-v-21ae3380><span class="doc-subsection__num" data-v-21ae3380>2.2</span> Third-Party &amp; Vendor Compliance </h3><p data-v-21ae3380> All external partners, independent contractors, and freelance contributors are legally bound by these prohibitions. </p><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>A</span> Contractual Obligation </h4><p data-v-21ae3380> All service agreements and statements of work must include a clause explicitly forbidding the use of Generative AI in the delivery of services. Vendors must warrant that all deliverables are human-made. </p></div><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>B</span> Indemnification </h4><p data-v-21ae3380> Any vendor found to have utilized Generative AI in violation of this policy shall be subject to immediate contract termination and financial liability for any legal damages incurred due to copyright infringement or intellectual property disputes arising from the use of such tools. </p></div><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>C</span> Verification </h4><p data-v-21ae3380> We reserve the right to request proof of the creative process (e.g., project files, time-lapse recordings, raw footage) to verify the authenticity of vendor deliverables. </p></div></div></section><section id="section-3" class="doc-section" data-v-21ae3380><h2 class="doc-section__title" data-v-21ae3380><span class="doc-section__num" data-v-21ae3380>§3</span> Approved Technical AI Uses </h2><div class="doc-subsection" data-v-21ae3380><h3 class="doc-subsection__title" data-v-21ae3380><span class="doc-subsection__num" data-v-21ae3380>3.1</span> Coding &amp; Technical Assistance </h3><p data-v-21ae3380> The use of AI is permitted solely for non-creative, technical assistance where it functions as a productivity tool rather than a creator. Permitted uses include: </p><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>A</span> Syntax and Debugging </h4><p data-v-21ae3380> Utilizing AI-powered code completion tools (e.g., predictive text editors) to suggest syntax, identify logical errors, or explain standard library functions. </p></div><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>B</span> Script Automation </h4><p data-v-21ae3380> Generating small scripts for build processes, file management, or data parsing. This excludes the generation of core product architecture or proprietary algorithms. </p></div><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>C</span> Documentation </h4><p data-v-21ae3380> Assisting in the formatting or grammatical correction of technical documentation, provided that the technical content and logic are human-derived. </p></div><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>D</span> Learning &amp; Research </h4><p data-v-21ae3380> Using AI chatbots to explain technical concepts, research generic solutions to common problems, or summarize public documentation. </p></div></div><div class="doc-subsection" data-v-21ae3380><h3 class="doc-subsection__title" data-v-21ae3380><span class="doc-subsection__num" data-v-21ae3380>3.2</span> Data Security &amp; Privacy </h3><p data-v-21ae3380> Strict rules govern the input of data into AI models to prevent security breaches and intellectual property leakage. </p><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>A</span> Prohibition on Proprietary Data </h4><p data-v-21ae3380> Under no circumstances shall proprietary code, sensitive user data, personal identifiable information (PII), trade secrets, or internal strategic documents be uploaded to public AI models or unvetted third-party services. </p></div><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>B</span> Vetted Enterprise Solutions </h4><p data-v-21ae3380> Only AI tools hosted on private, secure servers with strict data retention policies (i.e., “no-training” guarantees) may be used for technical tasks. Public, consumer-grade AI interfaces are strictly prohibited for any work-related technical tasks. </p></div><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>C</span> Audit Trail </h4><p data-v-21ae3380> Developers must maintain a log of AI-assisted technical tasks. This log must specify the tool used and the nature of the assistance provided (e.g., “Syntax correction on line 40”). </p></div></div></section><section id="section-4" class="doc-section" data-v-21ae3380><h2 class="doc-section__title" data-v-21ae3380><span class="doc-section__num" data-v-21ae3380>§4</span> Transparency, Accountability &amp; Safeguards </h2><div class="doc-subsection" data-v-21ae3380><h3 class="doc-subsection__title" data-v-21ae3380><span class="doc-subsection__num" data-v-21ae3380>4.1</span> Disclosure &amp; Proof of Authenticity </h3><p data-v-21ae3380> To maintain trust with clients and the audience, a policy of transparency is enforced. </p><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>A</span> Public Declaration </h4><p data-v-21ae3380> All releases shall include a statement affirming that the work is 100% human-made. This declaration serves as a mark of quality and ethical production. </p></div><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>B</span> Audit Trails </h4><p data-v-21ae3380>For every project, a comprehensive audit trail must be maintained. This includes:</p><ul class="doc-list" data-v-21ae3380><li data-v-21ae3380>Raw project files (e.g., .PSD, .AI, .BLEND, .WAV)</li><li data-v-21ae3380>Version history showing progressive changes</li><li data-v-21ae3380>Source footage and raw audio recordings</li><li data-v-21ae3380>Notes and sketches from the conceptual phase</li></ul></div><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>C</span> Asset Rejection </h4><p data-v-21ae3380> Any asset suspected of being AI-generated will be immediately rejected. The burden of proof lies with the creator to demonstrate the human origin of the asset. Failure to provide adequate proof of the creative process will result in the rejection of the deliverable. </p></div></div><div class="doc-subsection" data-v-21ae3380><h3 class="doc-subsection__title" data-v-21ae3380><span class="doc-subsection__num" data-v-21ae3380>4.2</span> Internal Oversight &amp; Enforcement </h3><p data-v-21ae3380> Compliance with this policy is mandatory. Violations will be met with swift and decisive action. </p><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>A</span> Regular Audits </h4><p data-v-21ae3380> Internal audits will be conducted periodically to ensure adherence to this policy. These audits will review project files, technical logs, and vendor contracts. </p></div><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>B</span> Consequences for Violations </h4><p data-v-21ae3380> Violations of this policy will result in disciplinary action, up to and including: </p><ul class="doc-list" data-v-21ae3380><li data-v-21ae3380>Immediate termination of employment or contract.</li><li data-v-21ae3380>Forfeiture of payment for the offending work.</li><li data-v-21ae3380> Legal action for breach of contract and potential copyright infringement. </li><li data-v-21ae3380> Blacklisting of the vendor or contractor from future projects. </li></ul></div><div class="doc-point" data-v-21ae3380><h4 class="doc-point__label" data-v-21ae3380><span class="doc-point__letter" data-v-21ae3380>C</span> Reporting Mechanism </h4><p data-v-21ae3380> Any team member or contractor who becomes aware of a violation of this policy is obligated to report it immediately to the designated compliance officer. </p></div></div></section><section id="section-5" class="doc-section" data-v-21ae3380><h2 class="doc-section__title" data-v-21ae3380><span class="doc-section__num" data-v-21ae3380>§5</span> Conclusion </h2><p data-v-21ae3380> This policy exists to protect the integrity of the craft and the rights of human creators. By adhering to these restrictions, all contributors ensure that the work produced remains authentic, legally secure, and distinctly human. </p></section></article><footer class="doc-footer" data-v-21ae3380><p class="doc-footer__line" data-v-21ae3380>End of document</p><p class="doc-footer__id" data-v-21ae3380>AIP-2024-001 · Revision 1.0</p></footer></div></section>`)})}),n=o.setup;o.setup=(a,e)=>{const i=t.useSSRContext();return(i.modules||(i.modules=new Set)).add("pages/ai.vue"),n?n(a,e):void 0};const c=e(o,[["__scopeId","data-v-21ae3380"]]);export{c as default};
//# sourceMappingURL=ai-CEFn8_iF.mjs.map
